use ieee.std_logic_1164.all;
use ieee.std_logic_textio.all;

use std.textio.all;
use std.env.all;

entity harness is
end entity harness;

architecture sim of harness is
    signal data_sig  : std_logic_vector(3 downto 0);
    signal index_sig : std_logic_vector(1 downto 0);
    signal valid_sig : std_logic;
begin
    dut : entity work.solution
        port map (
            data  => data_sig,
            index => index_sig,
            valid => valid_sig
        );

    process
        variable in_line  : line;
        variable out_line : line;
        variable data_in  : std_logic_vector(3 downto 0);
    begin
        readline(input, in_line);
        read(in_line, data_in);
        data_sig <= data_in;
        wait for 1 ns;
        write(out_line, index_sig);
        write(out_line, valid_sig);
        writeline(output, out_line);
        finish;
    end process;
end architecture sim;

